package fr.cercle.milledestins;
import android.app.Activity;import android.os.Bundle;import android.os.Build;import android.content.Intent;import android.content.SharedPreferences;import android.net.Uri;import android.graphics.Color;import android.view.WindowInsets;import android.view.View;import android.webkit.*;import android.widget.Toast;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class MainActivity extends Activity {
 private WebView web;private SharedPreferences prefs;private String pendingExport;private static final int EXPORT=40,IMPORT=41;private static final String ORIGIN="https://appassets.androidplatform.net/";private static final int MAX=2*1024*1024;
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("mille_destins",MODE_PRIVATE);getWindow().setStatusBarColor(Color.rgb(8,14,24));getWindow().setNavigationBarColor(Color.rgb(8,14,24));web=new WebView(this);web.setBackgroundColor(Color.rgb(8,14,24));setContentView(web);
 web.setOnApplyWindowInsetsListener((v,insets)->{int l,t,r,bt;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets x=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());l=x.left;t=x.top;r=x.right;bt=x.bottom;}else{l=insets.getSystemWindowInsetLeft();t=insets.getSystemWindowInsetTop();r=insets.getSystemWindowInsetRight();bt=insets.getSystemWindowInsetBottom();}v.setPadding(l,t,r,bt);return insets;});
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);s.setMediaPlaybackRequiresUserGesture(true);s.setTextZoom(100);if(Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);CookieManager.getInstance().setAcceptCookie(false);web.addJavascriptInterface(new Bridge(),"Android");web.setWebChromeClient(new WebChromeClient());
 web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest req){Uri u=req.getUrl();if(!"https".equals(u.getScheme())||!"appassets.androidplatform.net".equals(u.getHost()))return denied();String p=u.getPath();if(p==null||p.equals("/"))p="/index.html";if(p.contains("..")||p.indexOf('\\')>=0)return denied();try{String mime=p.endsWith(".html")?"text/html":p.endsWith(".css")?"text/css":p.endsWith(".js")?"text/javascript":p.endsWith(".svg")?"image/svg+xml":p.endsWith(".png")?"image/png":"application/octet-stream";Map<String,String> headers=new HashMap<>();headers.put("X-Content-Type-Options","nosniff");headers.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; object-src 'none'; frame-src 'none'; base-uri 'none'");return new WebResourceResponse(mime,mime.startsWith("image/")?null:"UTF-8",200,"OK",headers,getAssets().open(p.substring(1)));}catch(IOException e){return denied();}}
 @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){return !req.getUrl().toString().startsWith(ORIGIN);} });if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->handleBack());web.loadUrl(ORIGIN+"index.html");}
 private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
 public final class Bridge {
 @JavascriptInterface public String readLibrary(){return prefs.getString("library","");}
 @JavascriptInterface public String readLibraryBackup(){return prefs.getString("backup","");}
 @JavascriptInterface public synchronized boolean writeLibrary(String json){if(json==null||json.length()>MAX)return false;try{JSONObject o=new JSONObject(json);if(o.optInt("schema")!=1||!(o.opt("stories") instanceof JSONObject))return false;String old=prefs.getString("library","");SharedPreferences.Editor editor=prefs.edit();try{JSONObject previous=new JSONObject(old);if(previous.optInt("schema")==1&&previous.opt("stories") instanceof JSONObject)editor.putString("backup",old);}catch(Exception ignored){}return editor.putString("library",json).commit();}catch(Exception e){return false;}}
 @JavascriptInterface public void exportSave(String json){if(json==null||json.length()>MAX)return;runOnUiThread(()->{pendingExport=json;try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"mille-destins-carnet.json");startActivityForResult(i,EXPORT);}catch(Exception e){notice("Aucun gestionnaire de documents disponible.");}});}
 @JavascriptInterface public void importSave(){runOnUiThread(()->{try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}catch(Exception e){notice("Aucun gestionnaire de documents disponible.");}});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=EXPORT&&request!=IMPORT)return;if(result!=RESULT_OK||data==null||data.getData()==null){if(request==EXPORT)pendingExport=null;return;}Uri uri=data.getData();if(request==EXPORT){String text=pendingExport;pendingExport=null;if(text==null)return;new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(text.getBytes(StandardCharsets.UTF_8));runOnUiThread(()->notice("Carnet exporté."));}catch(Exception e){runOnUiThread(()->notice("Le carnet n’a pas pu être exporté."));}}).start();}else new Thread(()->{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>MAX)throw new IOException();out.write(buffer,0,n);}String text=new String(out.toByteArray(),StandardCharsets.UTF_8);runOnUiThread(()->{if(!isFinishing())web.evaluateJavascript("window.importNativeSave("+JSONObject.quote(text)+")",null);});}catch(Exception e){runOnUiThread(()->notice("Ce carnet est illisible ou trop volumineux."));}}).start();}
 private void notice(String message){if(!isFinishing())Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
 @Override public void onBackPressed(){handleBack();}
 private void handleBack(){web.evaluateJavascript("Boolean(window.onNativeBack && window.onNativeBack())",value->{if(!"true".equals(value))finish();});}
 @Override protected void onPause(){web.evaluateJavascript("window.dispatchEvent(new Event('pagehide'))",null);web.onPause();super.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.onResume();}
 @Override protected void onDestroy(){web.removeJavascriptInterface("Android");web.destroy();super.onDestroy();}
}
